          title: "Every view is a fold over the same events",
          code: `function apply(cart, e) {                    // one step of the fold
  if (e.type === "ItemAdded")   return { ...cart, [e.item]: (cart[e.item] || 0) + 1 };
  if (e.type === "ItemRemoved") { const { [e.item]: _, ...rest } = cart; return rest; }
  return cart;                                  // ignore events this view doesn't use
}
const cartNow  = events.reduce(apply, {});              // { book: 1, pen: 1, mug: 1 }
const cartThen = events.slice(0, 4).reduce(apply, {});  // after #4: { book: 1, pen: 1 }

// A view invented today, computed from events recorded months ago:
const removals = events.filter(e => e.type === "ItemRemoved")
  .reduce((n, e) => ({ ...n, [e.item]: (n[e.item] || 0) + 1 }), {});  // { mug: 1, lamp: 1 }`,
          caption: "Nothing inside <code>apply</code> reads the clock, generates a random number or calls the network. Any value like that (a timestamp, a price quote, an exchange rate) is recorded in the event when it is created, so every replay gives the same answer.",
